# A set of pivots only removes points comparable with a pivot. For the
# permutation order, the surviving set is generated by the tightest pivot
# neighborhood; collect those neighborhoods and the no-operation outcome.
sets={tuple(range(n))}
for k,(x,y) in enumerate(pts):
    survivors=[]
    for i,(a,b) in enumerate(pts):
        if i==k or (a-x)*(b-y)<0:
            survivors.append(i)
    sets.add(tuple(survivors))
print(len(sets))

