import sys

MOD = 998244353

def factorize(x):
    out = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            e = 0
            while x % d == 0:
                x //= d
                e += 1
            out.append((d, e))
        d += 1
    if x > 1:
        out.append((x, 1))
    return out

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    factors = [factorize(x) for x in a]
    primes = {}
    for i, fs in enumerate(factors):
        for p, e in fs:
            primes.setdefault(p, [0] * (n - 1))[i] = e

    answer = 1
    for p, steps in primes.items():
        # dp[h] is the total weight of prefixes whose current height above
        # their minimum is h. The weight is p to the sum of these heights.
        dp = [1]
        t = 1  # number of vertices already processed
        for step in steps:
            if step == 0:
                ndp = [0] * len(dp)
                for h, val in enumerate(dp):
                    ndp[h] = (ndp[h] + val * pow(p, h, MOD)) % MOD
            else:
                ndp = [0] * (len(dp) + step)
                for h, val in enumerate(dp):
                    up = h + step
                    ndp[up] = (ndp[up] + val * pow(p, up, MOD)) % MOD
                    down = h - step
                    if down >= 0:
                        ndp[down] = (ndp[down] + val * pow(p, down, MOD)) % MOD
                    else:
                        # The new minimum is lower by -down; shift the t
                        # already-counted vertex heights accordingly.
                        mult = pow(p, -t * down, MOD)
                        ndp[0] = (ndp[0] + val * mult) % MOD
                # both signs are distinct choices, including when applicable
            dp = ndp
            t += 1
        answer = answer * (sum(dp) % MOD) % MOD
    print(answer)

if __name__ == '__main__':
    solve()

