import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    V = max(a)
    spf = list(range(V + 1))
    for p in range(2, int(V ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, V + 1, p):
                if spf[x] == x:
                    spf[x] = p
    phi = list(range(V + 1))
    for p in range(2, V + 1):
        if spf[p] == p:
            for x in range(p, V + 1, p):
                phi[x] -= phi[x] // p
    sums = [0] * (V + 1)
    ans = 0
    weight = 1
    out = []
    for x in a:
        y = x
        divs = [1]
        while y > 1:
            p = spf[y]
            e = 0
            while y % p == 0:
                y //= p
                e += 1
            old = divs[:]
            mul = 1
            for _ in range(e):
                mul *= p
                divs.extend(d * mul for d in old)
        c = 0
        for d in divs:
            c += phi[d] * sums[d]
        c %= MOD
        ans = (2 * ans + c) % MOD
        out.append(str(ans))
        for d in divs:
            v = sums[d] + weight
            if v >= MOD:
                v -= MOD
            sums[d] = v
        weight = weight * 2 % MOD
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

