from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            events[b].append((a, i))

        heap = []
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in events[right]:
                heapq.heappush(heap, (-left, idx))

            max_left = -heap[0][0] if heap else 0
            second_max = -heap[1][0] if len(heap) > 1 else 0
            total += right - max_left

            # Removing the unique constraint attaining max_left changes the
            # minimum valid start from max_left + 1 to second_max + 1.
            if heap and max_left > second_max:
                gains[heap[0][1]] += max_left - second_max

        return total + max(gains)

