from typing import List
import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events=[[] for _ in range(n+1)]
        for i,(a,b) in enumerate(conflictingPairs):
            if a>b: a,b=b,a
            events[b].append((a,i))
        heap=[]
        gain=[0]*len(conflictingPairs)
        base=0
        for r in range(1,n+1):
            for a,i in events[r]:
                heapq.heappush(heap,(-a,i))
            top=heap[0] if heap else (0,-1)
            largest=-top[0]
            second=-heap[1][0] if len(heap)>1 else 0
            base += r-largest
            if top[1]>=0 and largest>second:
                gain[top[1]] += largest-second
        return base+max(gain)

