import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)
    q = next(it)

    edges = []
    for _ in range(m):
        a = next(it) - 1
        b = next(it) - 1
        c = next(it)
        edges.append((a, b, c))

    queries = []
    closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            idx = next(it) - 1
            queries.append((1, idx))
            closed[idx] = True
        else:
            x = next(it) - 1
            y = next(it) - 1
            queries.append((2, x, y))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for idx, (a, b, c) in enumerate(edges):
        if not closed[idx]:
            dist[a][b] = dist[b][a] = c

    # All-pairs shortest paths in the graph after every forward deletion.
    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            row_i = dist[i]
            for j in range(n):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 1:
            a, b, w = edges[query[1]]
            # Adding one edge can improve a shortest path only by using it once.
            da = [dist[i][a] for i in range(n)]
            db = [dist[i][b] for i in range(n)]
            for i in range(n):
                row_i = dist[i]
                via_a = da[i] + w
                via_b = db[i] + w
                for j in range(i, n):
                    candidate1 = via_a + db[j]
                    candidate2 = via_b + da[j]
                    if candidate1 < row_i[j] or candidate2 < row_i[j]:
                        best = min(candidate1, candidate2)
                        row_i[j] = best
                        dist[j][i] = best
        else:
            value = dist[query[1]][query[2]]
            answers.append(str(value if value < inf else -1))

    sys.stdout.write('\n'.join(reversed(answers)))

if __name__ == '__main__':
    main()

