MOD = 10**9 + 7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        nbits = len(s)

        # factorials for combinations modulo MOD
        fact = [1] * (nbits + 1)
        for i in range(1, nbits + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * (nbits + 1)
        inv_fact[nbits] = pow(fact[nbits], MOD - 2, MOD)
        for i in range(nbits, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def choose(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        # If x > 1, its reduction count is 1 + depth(popcount(x)),
        # where depth(y) is the number of popcount operations to reach 1.
        allowed = [False] * (nbits + 1)
        for weight in range(1, nbits + 1):
            y = weight
            steps = 0
            while y > 1:
                y = y.bit_count()
                steps += 1
            allowed[weight] = steps <= k - 1

        # Scan the bound from left to right. At each 1, count numbers that
        # first differ here by choosing 0, with each allowed total weight.
        answer = 0
        used_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = nbits - i - 1
                for weight in range(1, nbits + 1):
                    if allowed[weight]:
                        answer += choose(remaining, weight - used_ones)
                used_ones += 1

        return answer % MOD

