import sys

def main():
    d = list(map(int, sys.stdin.buffer.read().split()))
    if not d:
        return
    n, m = d[0], d[1]
    rows = [0] * n
    pos = 2
    for _ in range(m):
        u, v = d[pos] - 1, d[pos + 1] - 1
        pos += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form over GF(2).
    pivots = []
    rank = 0
    for col in range(n):
        pivot_row = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if pivot_row is None:
            continue
        rows[rank], rows[pivot_row] = rows[pivot_row], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    null_basis = []
    for free_col in range(n):
        if free_col in pivot_set:
            continue
        vector = 1 << free_col
        for row_idx, pivot_col in enumerate(pivots):
            if (rows[row_idx] >> free_col) & 1:
                vector |= 1 << pivot_col
        null_basis.append(vector)

    # Use one independent bit for each nullspace basis vector.
    # Keeping these bits at the top also ensures all values fit in 60 bits.
    offset = n - len(null_basis)
    values = [0] * n
    for j, vector in enumerate(null_basis):
        for vertex in range(n):
            if (vector >> vertex) & 1:
                values[vertex] |= 1 << (offset + j)

    if any(value == 0 for value in values):
        print("No")
    else:
        print("Yes")
        print(*values)

if __name__ == "__main__":
    main()

