import math

N = int(input())

# Since N = d(3y^2 + 3dy + d^2), where d = x-y, and y >= 1,
# necessarily d^3 < N.
limit = 1
while (limit + 1) ** 3 < N:
    limit += 1

for d in range(1, limit + 1):
    if N % d:
        continue
    q = N // d
    # Discriminant of 3y^2 + 3dy + d^2 = q.
    disc = 12 * q - 3 * d * d
    if disc < 0:
        continue
    root = math.isqrt(disc)
    if root * root == disc and (root - 3 * d) % 6 == 0:
        y = (root - 3 * d) // 6
        if y > 0:
            print(y + d, y)
            break
else:
    print(-1)

