from typing import List
from array import array
class Solution:
 def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
  n=len(grid); m=len(grid[0]); N=n*m
  dirs=[(1,1),(1,-1),(-1,-1),(-1,1)]
  straight=[array('H',[0])*N for _ in range(4)]; turned=[array('H',[0])*N for _ in range(4)]
  def order(d):
   dr,dc=dirs[d]; return (range(n-1,-1,-1) if dr>0 else range(n), range(m-1,-1,-1) if dc>0 else range(m))
  for d,(dr,dc) in enumerate(dirs):
   rows,cols=order(d)
   for r in rows:
    for c in cols:
     v=grid[r][c]
     if v not in (0,2): continue
     rr=r+dr; cc=c+dc; val=1; idx=r*m+c
     if 0<=rr<n and 0<=cc<m and grid[rr][cc]==2-v: val+=straight[d][rr*m+cc]
     straight[d][idx]=val
  for d,(dr,dc) in enumerate(dirs):
   rows,cols=order(d); nd=(d+1)%4
   for r in rows:
    for c in cols:
     v=grid[r][c]
     if v not in (0,2): continue
     idx=r*m+c; t=straight[d][idx]
     rr=r+dr; cc=c+dc
     if 0<=rr<n and 0<=cc<m and grid[rr][cc]==2-v: t=max(t,1+turned[d][rr*m+cc])
     rr=r+dirs[nd][0]; cc=c+dirs[nd][1]
     if 0<=rr<n and 0<=cc<m and grid[rr][cc]==2-v: t=max(t,1+straight[nd][rr*m+cc])
     turned[d][idx]=t
  ans=0
  for r in range(n):
   for c in range(m):
    if grid[r][c]==1:
     ans=max(ans,1)
     for d,(dr,dc) in enumerate(dirs):
      rr=r+dr; cc=c+dc
      if 0<=rr<n and 0<=cc<m and grid[rr][cc]==2: ans=max(ans,1+turned[d][rr*m+cc])
  return ans

