class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        coeff = []
        for i in range(h):
            if n % 2 and i == h - 1:
                c = pow(10, n - 1 - i, k)
            else:
                c = (pow(10, i, k) + pow(10, n - 1 - i, k)) % k
            coeff.append(c)

        # dp[i] is a bitmask of residues obtainable using half-digits i onward.
        dp = [0] * (h + 1)
        dp[h] = 1  # Only residue 0 is obtainable from no digits.
        transitions = {}
        for c in set(coeff):
            table = [0] * (1 << k)
            contributions = {d * c % k for d in range(10)}
            for mask in range(1 << k):
                out = 0
                for residue in range(k):
                    if mask >> residue & 1:
                        for value in contributions:
                            out |= 1 << ((residue + value) % k)
                table[mask] = out
            transitions[c] = table

        for i in range(h - 1, -1, -1):
            dp[i] = transitions[coeff[i]][dp[i + 1]]

        chosen = []
        remainder = 0
        for i, c in enumerate(coeff):
            suffix = dp[i + 1]
            low = 1 if i == 0 else 0
            for digit in range(9, low - 1, -1):
                needed = (-remainder - digit * c) % k
                if suffix >> needed & 1:
                    chosen.append(str(digit))
                    remainder = (remainder + digit * c) % k
                    break

        left = ''.join(chosen)
        if n % 2:
            return left + left[-2::-1]
        return left + left[::-1]

