from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # next greater element to the right
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        # Binary lifting along successive prefix maxima. At index i, the
        # next link is the first later position whose value exceeds nums[i].
        levels = n.bit_length()
        jumps = [nxt]
        block_sums = [[nums[i] * (nxt[i] - i) for i in range(n)]]
        for _ in range(1, levels):
            prev_jump = jumps[-1]
            prev_sum = block_sums[-1]
            curr_jump = [n] * n
            curr_sum = [0] * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    curr_jump[i] = prev_jump[mid]
                    curr_sum[i] = prev_sum[i] + prev_sum[mid]
                else:
                    curr_sum[i] = prev_sum[i]
            jumps.append(curr_jump)
            block_sums.append(curr_sum)

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        def operations(left: int, right: int) -> int:
            # Sum of prefix maxima minus the original elements' sum.
            pos = left
            maximum_sum = 0
            for level in range(levels - 1, -1, -1):
                end = jumps[level][pos]
                if end <= right:
                    maximum_sum += block_sums[level][pos]
                    pos = end
            maximum_sum += nums[pos] * (right - pos + 1)
            return maximum_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        for right in range(n):
            low, high = 0, right
            while low < high:
                mid = (low + high) // 2
                if operations(mid, right) <= k:
                    high = mid
                else:
                    low = mid + 1
            answer += right - low + 1
        return answer

