  for i in range(n-1,-1,-1):
   while st and nums[st[-1]]<=nums[i]: st.pop()
   nxt[i]=st[-1] if st else n; st.append(i)
  LOG=n.bit_length(); jump=[nxt]; sums=[[nums[i]*(nxt[i]-i) for i in range(n)]]
  for j in range(1,LOG):
   prev=jump[-1]; ps=sums[-1]; nj=[n]*n; ns=[0]*n
   for i in range(n):
    m=prev[i]
    if m<n: nj[i]=prev[m]; ns[i]=ps[i]+ps[m]
    else: ns[i]=ps[i]
   jump.append(nj); sums.append(ns)
  pref=[0]
  for x in nums: pref.append(pref[-1]+x)
  def cost(l,r):
   cur=l; sm=0
