    z=jump[j][cur]
    if z<=r:
     sm+=sums[j][cur]; cur=z
   sm+=nums[cur]*(r-cur+1)
   return sm-(pref[r+1]-pref[l])
  ans=0
  for r in range(n):
   lo,hi=0,r
   while lo<hi:
    mid=(lo+hi)//2
    if cost(mid,r)<=k: hi=mid
    else: lo=mid+1
   ans+=r-lo+1
