import sys
from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]
    funcs = [(data[i], data[i + 1]) for i in range(2, len(data), 2)]

    # For two functions i and j, putting i outside j is at least as good
    # exactly when (A_i - 1) / B_i >= (A_j - 1) / B_j.
    # Thus an optimal sequence uses functions in increasing ratio from
    # innermost to outermost.
    def compare(x, y):
        left = (x[0] - 1) * y[1]
        right = (y[0] - 1) * x[1]
        return (left > right) - (left < right)

    funcs.sort(key=cmp_to_key(compare))
    dp = [None] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for count in range(k, 0, -1):
            if dp[count - 1] is not None:
                value = a * dp[count - 1] + b
                if dp[count] is None or value > dp[count]:
                    dp[count] = value
    print(dp[k])

if __name__ == '__main__':
    main()

