from array import array

class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        dp = array('I', [0]) * (n * n)
        for i, x in enumerate(nums):
            dp[i * n + i] = x

        # XOR score of [i, j] is score(i, j-1) XOR score(i+1, j).
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                dp[i * n + j] = dp[i * n + j - 1] ^ dp[(i + 1) * n + j]

        # Convert scores into the maximum score of any subinterval.
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                k = i * n + j
                dp[k] = max(dp[k], dp[k + n], dp[k - 1])

        return [dp[l * n + r] for l, r in queries]

