class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - ord('a')] += 1

        # For a fixed final frequency k, process letters from left to right.
        # dp[m] is the minimum cost after the previous letter, with m copies
        # converted into the current letter. At a letter, either remove it
        # entirely or retain k copies; any extra copies may be passed on.
        # An optimal frequency can be taken to be 1 or an initial frequency:
        # between such frequencies the choices and costs are linear, so an
        # interior value cannot improve on both endpoints.
        ans = len(s)
        targets = {1}
        targets.update(x for x in cnt if x)
        for k in targets:
            dp = {0: 0}
            for c in cnt:
                nd = {}
                for carry, cost in dp.items():
                    total = c + carry
                    for moved in range(min(k, total) + 1):
                        # Make this character absent: delete all copies not moved.
                        v = cost + total
                        if v < nd.get(moved, 10**30):
                            nd[moved] = v

                        # Keep k copies, inserting any shortfall. Retain as many
                        # existing copies as possible for this chosen moved count.
                        retained = min(k, total - moved)
                        v = cost + k + total - 2 * retained
                        if v < nd.get(moved, 10**30):
                            nd[moved] = v
                dp = nd
            # Copies moved beyond z cannot be used and must be deleted.
            ans = min(ans, min(cost + moved for moved, cost in dp.items()))
        return ans

