                    for wanted in (0,k):
                        # Select r existing copies to keep here, insert if needed;
                        # send m to the next letter and delete all other copies.
                        lo=max(0,total-wanted)
                        hi=min(total,k)
                        for m in range(lo, min(hi,k)+1):
