from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, M, L = data[:3]
    values = data[3:]
    total = N + M + L
    all_cards = (1 << total) - 1

    takahashi = (1 << N) - 1
    aoki = ((1 << M) - 1) << N

    @lru_cache(None)
    def can_win(t_hand, a_hand, turn):
        hand = t_hand if turn == 0 else a_hand
        if hand == 0:
            return False

        table = all_cards ^ t_hand ^ a_hand
        while hand:
            card = hand & -hand
            hand -= card
            i = card.bit_length() - 1

            next_t = t_hand ^ card if turn == 0 else t_hand
            next_a = a_hand ^ card if turn == 1 else a_hand

            # Play the card without taking anything from the table.
            if not can_win(next_t, next_a, 1 - turn):
