from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            # Prefix function for KMP.
            pi = [0] * len(t)
            j = 0
            for i in range(1, len(t)):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                    pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                    if j == len(t):
                        result.append(i - len(t) + 1)
                        j = pi[j - 1]
            return result

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)

        answer = n + 1
        for start_a in starts_a:
            idx_b = bisect_left(starts_b, start_a + len(a))
            if idx_b == len(starts_b):
                continue
            start_b = starts_b[idx_b]

            idx_c = bisect_left(starts_c, start_b + len(b))
            if idx_c == len(starts_c):
                continue
            start_c = starts_c[idx_c]
            answer = min(answer, start_c + len(c) - start_a)

        return -1 if answer == n + 1 else answer

