    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    k = 2
    for _ in range(m):
        x, y, z = data[k] - 1, data[k + 1] - 1, data[k + 2]
        k += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    value = [None] * n
    answer = [0] * n
    for start in range(n):
        if value[start] is not None:
            continue
        value[start] = 0
        queue = [start]
        component = []
        for v in queue:
            component.append(v)
            for w, z in graph[v]:
                candidate = value[v] ^ z
                if value[w] is None:
                    value[w] = candidate
                    queue.append(w)
                elif value[w] != candidate:
                    print(-1)
                    return

        offset = 0
        for bit in range(30):
            ones = sum((value[v] >> bit) & 1 for v in component)
            if 2 * ones > len(component):
                offset |= 1 << bit
        for v in component:
            answer[v] = value[v] ^ offset

    print(*answer)

if __name__ == '__main__':
    main()

