import sys

def solve():
    data = sys.stdin.buffer.read().split()
    k = int(data[0])
    a, b = data[1], data[2]
    n, m = len(a), len(b)
    if abs(n - m) > k:
        print('No')
        return

    # For each edit count and diagonal d = i - j, retain the greatest i
    # reachable after greedily consuming equal characters.
    i = 0
    while i < n and i < m and a[i] == b[i]:
        i += 1
    if i == n and i == m:
        print('Yes')
        return
    v = {0: i}

    for edits in range(1, k + 1):
        nv = {}
        for d in range(-edits, edits + 1):
            best = -1

            # Delete from a: diagonal increases by 1.
            x = v.get(d - 1, -1)
            if x >= 0:
                j = x - (d - 1)
                if x < n and 0 <= j <= m:
                    best = x + 1

            # Insert from b: diagonal decreases by 1.
            x = v.get(d + 1, -1)
            if x >= 0:
                j = x - (d + 1)
                if 0 <= x <= n and j < m and x > best:
                    best = x

            # Replace one character: diagonal stays unchanged.
            x = v.get(d, -1)
            if x >= 0:
                j = x - d
                if x < n and 0 <= j < m and x + 1 > best:
                    best = x + 1

            if best < 0:
                continue
            j = best - d
            while best < n and j < m and a[best] == b[j]:
                best += 1
                j += 1
            nv[d] = best
            if best == n and j == m:
                print('Yes')
                return
        v = nv

    print('No')

if __name__ == '__main__':
    solve()

