from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Build the exact postorder produced by DFS. Iterative traversal avoids
        # recursion-depth issues on a long chain.
        post = []
        stack = [(0, False)]
        while stack:
            u, done = stack.pop()
            if done:
                post.append(u)
            else:
                stack.append((u, True))
                for v in reversed(children[u]):
                    stack.append((v, False))

        pos = [0] * n
        chars = []
        for i, u in enumerate(post):
            pos[u] = i
            chars.append(s[u])
        t = ''.join(chars)

        # Subtree sizes, accumulated bottom-up in postorder.
        size = [1] * n
        for u in post:
            if parent[u] != -1:
                size[parent[u]] += size[u]

        # Manacher radii for odd- and even-length palindromes.
        odd = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < n and t[i - k] == t[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        even = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < n and t[i - k - 1] == t[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        answer = [False] * n
        for u in range(n):
            right = pos[u]
            left = right - size[u] + 1
            length = size[u]
            if length % 2:
                center = (left + right) // 2
                answer[u] = odd[center] >= length // 2 + 1
            else:
                center = (left + right + 1) // 2
                answer[u] = even[center] >= length // 2
        return answer

