from typing import List

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def score(arr: List[int]) -> int:
            if not arr:
                return 0
            g = 0
            l = 1
            for x in arr:
                g = gcd(g, x)
                l = l // gcd(l, x) * x
            return g * l

        best = score(nums)
        for i in range(len(nums)):
            best = max(best, score(nums[:i] + nums[i + 1:]))
        return best

