limit = S // 2

sieve = bytearray(b'\x01') * (limit + 1)
if limit >= 0:
    sieve[0] = 0
if limit >= 1:
    sieve[1] = 0
for i in range(2, math.isqrt(limit) + 1):
    if sieve[i]:
        start = i * i
        sieve[start:limit + 1:i] = b'\x00' * (((limit - start) // i) + 1)
primes = [i for i in range(2, limit + 1) if sieve[i]]

answer = 0
# Numbers of the form p^2 q^2, where p and q are distinct primes.
for idx, p in enumerate(primes):
    if p * p >= S:
        break
    answer += bisect.bisect_right(primes, S // p) - idx - 1

# Numbers of the form p^8.
for p in primes:
    if p ** 8 <= N:
        answer += 1
    else:
        break

print(answer)

