class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def can_transform(a: int, target: int) -> bool:
            digits = list(str(a))
            for i in range(len(digits)):
                for j in range(i + 1, len(digits)):
                    digits[i], digits[j] = digits[j], digits[i]
                    if int(''.join(digits)) == target:
                        return True
                    digits[i], digits[j] = digits[j], digits[i]
            return False

        pairs = 0
        for i in range(len(nums)):
            for j in range(i):
                a, b = nums[i], nums[j]
                if a == b or can_transform(a, b) or can_transform(b, a):
                    pairs += 1
        return pairs

