class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        counts = Counter(nums)
        largest = None

        for outlier in counts:
            remaining = total - outlier
            if remaining % 2 != 0:
                continue

            sum_value = remaining // 2
            required = 1 + (outlier == sum_value)
            if counts.get(sum_value, 0) >= required:
                if largest is None or outlier > largest:
                    largest = outlier

        return largest

