import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, 100):
            if is_prime[p]:
                for x in range(p * p, limit, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1

        digits = len(str(n))
        low = 1 if digits == 1 else 10 ** (digits - 1)
        high = 10 ** digits - 1
        inf = float('inf')
        dist = [inf] * limit
        dist[n] = n  # The initial value is included in the transformation cost.
        pq = [(n, n)]

        while pq:
            cost, value = heapq.heappop(pq)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            place = 1
            for _ in range(digits):
                digit = (value // place) % 10
                for delta in (-1, 1):
                    new_digit = digit + delta
                    if not 0 <= new_digit <= 9:
                        continue
                    nxt = value + delta * place
                    if not low <= nxt <= high or is_prime[nxt]:
                        continue
                    new_cost = cost + nxt
                    if new_cost < dist[nxt]:
                        dist[nxt] = new_cost
                        heapq.heappush(pq, (new_cost, nxt))
                place *= 10

        return -1

