from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0
        for i in range(1, n - 1):
            # First subarray is a prefix of the second. The second must
            # have length at least i, so its endpoint is at least 2*i.
            first_condition = z[i] >= i
            if first_condition and 2 * i < n:
                answer += n - 2 * i

            # For each possible second-subarray length d, test whether it
            # is a prefix of the following subarray using a Z-function on
            # nums[i:].
            suffix = nums[i:]
            m = len(suffix)
            q = [0] * m
            l = r = 0
            for x in range(1, m):
                if x < r:
                    q[x] = min(r - x, q[x - l])
                while x + q[x] < m and suffix[q[x]] == suffix[x + q[x]]:
                    q[x] += 1
                if x + q[x] > r:
                    l, r = x, x + q[x]

            for d in range(1, m):
                if q[d] >= d and not (first_condition and d >= i):
                    answer += 1

        return answer

