import heapq
class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev = [[] for _ in range(n)]
        for a,b,w in edges:
            rev[b].append((a,w))
        inf = 10**18
        d = [inf]*n
        d[0] = 0
        pq = [(0,0)]
        while pq:
            cost,v = heapq.heappop(pq)
            if cost != d[v]:
                continue
            for u,w in rev[v]:
                nd = max(cost,w)
                if nd < d[u]:
                    d[u] = nd
                    heapq.heappush(pq,(nd,u))
        ans = max(d)
        return -1 if ans == inf else ans

