class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        best_gain = 0
        # An eligible 1-run must have zero-runs on both sides, and those
        # zero-runs must themselves be bounded by 1-runs.
        for i in range(2, len(runs) - 2):
            if runs[i][0] == '1' and runs[i - 1][0] == '0' and runs[i + 1][0] == '0':
                best_gain = max(best_gain, runs[i - 1][1] + runs[i + 1][1])

        return s.count('1') + best_gain

